function appKeyToBytes(appKey: string): Uint8Array<ArrayBuffer> {
  // App key is 64 hex chars (256-bit, from PBKDF2 / SHA-256) -> 32 raw bytes. No 0x prefix.
  const out = new Uint8Array(new ArrayBuffer(appKey.length / 2));
